/**
 * Moves every issue from `sourceId` onto `targetId` and drops the source label,
 * all in one transaction. Returns how many issues carried the source label.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceId: LabelId,
  targetId: LabelId,
): Promise<number> {
  if (sourceId === targetId) {
    throw new Error("Cannot merge a label into itself");
  }

  return getDb().transaction((tx) => {
    const sourceIssueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceId),
        ),
      )
      .all()
      .map((row) => row.issueId);

    const alreadyTargeted = new Set(
      sourceIssueIds.length === 0
        ? []
        : tx
            .select({ issueId: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, orgId),
                eq(issueLabels.labelId, targetId),
                inArray(issueLabels.issueId, sourceIssueIds),
              ),
            )
            .all()
            .map((row) => row.issueId),
    );

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceId),
        ),
      )
      .run();

    const toInsert = sourceIssueIds.filter((id) => !alreadyTargeted.has(id));
    if (toInsert.length > 0) {
      tx.insert(issueLabels)
        .values(
          toInsert.map((issueId) => ({ orgId, issueId, labelId: targetId })),
        )
        .run();
    }

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceId)))
      .run();

    return sourceIssueIds.length;
  });
}
